#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factorialCache;

long long quickExponentiation(long long base, long long exp) {
    long long result = 1LL;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long combination(int n, int r) {
    if (r == 0 || r == n) return 1LL;
    if (r > n || r < 0) return 0LL;
    long long numerator = factorialCache[n];
    long long denominator = (factorialCache[r] * factorialCache[n - r]) % MOD;
    return (numerator * quickExponentiation(denominator, MOD - 2)) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    int t = 1;
    while (t-- > 0) {
        istringstream iss(line);
        int n;
        long long kVal;
        iss >> n >> kVal;
        factorialCache.assign(n + 1, 1LL);
        for (int i = 1; i <= n; i++) {
            factorialCache[i] = (factorialCache[i - 1] * i) % MOD;
        }
        if (kVal == 0) {
            cout << factorialCache[n] << "\n";
        } else if (kVal >= n) {
            cout << 0 << "\n";
        } else {
            int k = (int) kVal;
            long long totalSum = 0LL;
            long long signFlag = 1LL;
            int l = n - k;
            for (int i = 0; i <= l; i++) {
                long long term = (quickExponentiation(l - i, n) * combination(l, l - i)) % MOD;
                totalSum = (totalSum + signFlag * term + MOD) % MOD;
                signFlag *= -1LL;
            }
            long long answer = (2LL * combination(n, k) * totalSum) % MOD;
            cout << answer << "\n";
        }
        // Read next line for potential multiple test cases if needed
        if (t > 0) {
            getline(cin, line);
        }
    }
    return 0;
}
